@push('page-styles')
<style>
    .customer-account{min-height:75vh;padding:150px 20px 80px;background:#f6f7f9;color:#172033}.account-shell{width:min(1180px,100%);margin:auto}.account-heading{display:flex;justify-content:space-between;gap:20px;align-items:end;margin-bottom:24px}.account-heading small{color:#64748b;font-weight:800;letter-spacing:.12em;text-transform:uppercase}.account-heading h1{margin:7px 0 0;font-size:clamp(32px,5vw,54px);line-height:1.05}.account-heading p{max-width:620px;margin:8px 0 0;color:#64748b;line-height:1.7}.account-navigation{display:flex;align-items:center;gap:8px;margin-bottom:20px;padding:8px;border:1px solid #e2e8f0;border-radius:14px;background:#fff}.account-navigation a,.account-navigation button{display:flex;align-items:center;gap:8px;padding:10px 13px;border:0;border-radius:9px;background:transparent;color:#475569;font:inherit;font-size:13px;font-weight:800;text-decoration:none;cursor:pointer}.account-navigation a.active,.account-navigation a:hover,.account-navigation button:hover{background:#172033;color:#fff}.account-navigation form{margin-left:auto}.account-stats{display:grid;grid-template-columns:repeat(4,1fr);gap:13px;margin-bottom:20px}.account-stat,.account-panel{border:1px solid #e2e8f0;border-radius:16px;background:#fff;box-shadow:0 10px 30px rgba(15,23,42,.035)}.account-stat{padding:18px}.account-stat small,.account-stat strong{display:block}.account-stat small{color:#64748b}.account-stat strong{margin-top:7px;font-size:28px}.account-panel{overflow:hidden}.account-panel-heading{display:flex;align-items:center;justify-content:space-between;gap:15px;padding:17px 19px;border-bottom:1px solid #edf0f5}.account-panel-heading h2{margin:0;font-size:18px}.account-panel-heading a{color:#0f766e;font-weight:800;text-decoration:none}.account-table-wrap{overflow-x:auto}.account-table{width:100%;min-width:760px;border-collapse:collapse}.account-table th{padding:11px 15px;background:#f8fafc;color:#64748b;font-size:10px;letter-spacing:.08em;text-align:left;text-transform:uppercase}.account-table td{padding:15px;border-top:1px solid #edf0f5;font-size:13px}.account-table td strong,.account-table td small{display:block}.account-table td small{margin-top:4px;color:#94a3b8}.account-status{display:inline-block;padding:6px 9px;border-radius:999px;background:#f1f5f9;color:#475569;font-size:10px;font-weight:900;text-transform:uppercase}.account-status.processing,.account-status.shipped{background:#dbeafe;color:#1d4ed8}.account-status.completed,.account-status.delivered,.account-status.paid{background:#d1fae5;color:#047857}.account-status.cancelled,.account-status.refunded,.account-status.failed{background:#ffe4e6;color:#be123c}.account-action{display:inline-flex;align-items:center;gap:6px;padding:8px 10px;border-radius:8px;background:#ecfdf5;color:#047857;font-weight:800;text-decoration:none}.account-empty{padding:50px 20px;text-align:center;color:#64748b}.account-empty i{font-size:38px}.account-empty h3{margin:12px 0 5px;color:#172033}.account-filters{display:flex;gap:9px;padding:15px}.account-filters input{flex:1}.account-filters input,.account-filters select{min-height:42px;padding:9px 11px;border:1px solid #cbd5e1;border-radius:8px;background:#fff}.account-filters button,.account-filters a{padding:11px 14px;border:0;border-radius:8px;background:#172033;color:#fff;font-weight:800;text-decoration:none}.account-filters a{background:#f1f5f9;color:#475569}.account-pagination{padding:16px}.order-summary{display:grid;grid-template-columns:2fr 1fr;gap:18px}.order-card{padding:20px}.order-meta{display:grid;grid-template-columns:repeat(2,1fr);gap:13px}.order-meta div{padding:13px;border-radius:10px;background:#f8fafc}.order-meta small,.order-meta strong{display:block}.order-meta small{margin-bottom:4px;color:#64748b}.order-address{line-height:1.7;color:#475569}.order-actions{display:flex;flex-wrap:wrap;gap:9px}.order-actions a{padding:10px 12px;border-radius:8px;background:#172033;color:#fff;font-weight:800;text-decoration:none}.order-actions a.secondary{background:#ecfdf5;color:#047857}.profile-stack{display:grid;gap:18px}.profile-block{padding:22px}.profile-block form{max-width:680px}.profile-block input{max-width:100%}.profile-block header{margin-bottom:18px}.profile-block header h2{margin:0}.profile-block header p{margin:6px 0 0;color:#64748b}.profile-block .auth-field{margin-bottom:15px}.profile-block .auth-field label{display:block;margin-bottom:6px;font-size:12px;font-weight:850}.profile-block .auth-field input{width:100%;box-sizing:border-box;padding:11px 12px;border:1px solid #cbd5e1;border-radius:8px}.profile-block .auth-error{color:#be123c;font-size:12px}.profile-block .auth-submit{padding:11px 15px;border:0;border-radius:8px;background:#172033;color:#fff;font-weight:850;cursor:pointer}.profile-block .auth-status{margin-left:10px;color:#047857;font-size:13px}@media(max-width:800px){.account-stats{grid-template-columns:repeat(2,1fr)}.order-summary{grid-template-columns:1fr}}@media(max-width:600px){.customer-account{padding:115px 14px 55px}.account-heading{align-items:start;flex-direction:column}.account-navigation{align-items:stretch;flex-direction:column}.account-navigation form{margin-left:0}.account-navigation button{width:100%}.account-stats,.order-meta{grid-template-columns:1fr}.account-filters{flex-direction:column}}
</style>
@endpush
